#!/usr/bin/env node
import { Command } from 'commander';
import { createProject } from './generators/project';
import { addComponent } from './generators/component';

const program = new Command();

program
  .name('octo')
  .description('Octo CLI - Micro-frontend framework')
  .version('1.0.0');

program
  .command('create <project-name>')
  .description('Create a new Octo project')
  .option('-f, --framework <framework>', 'Framework (react|vue|svelte|preact)', 'react')
  .option('-s, --ssr', 'Enable server-side rendering', false)
  .option('-t, --typescript', 'Use TypeScript', false)
  .action(async (projectName, options) => {
    console.log(`Creating ${projectName} with ${options.framework}...`);
    await createProject(projectName, options);
    console.log('Project created successfully!');
  });

program
  .command('add <component-name>')
  .description('Add a new component')
  .option('-f, --framework <framework>', 'Component framework')
  .action(async (componentName, options) => {
    await addComponent(componentName, options);
  });

program.parse();

// octo-core/src/adapters/base.ts
export interface FrameworkAdapter {
  mount(element: HTMLElement, props: any): void;
  unmount(element: HTMLElement): void;
  update(element: HTMLElement, props: any): void;
}

// octo-core/src/adapters/react.ts
import React from 'react';
import ReactDOM from 'react-dom/client';
import { FrameworkAdapter } from './base';

export class ReactAdapter implements FrameworkAdapter {
  private root: ReactDOM.Root | null = null;

  mount(element: HTMLElement, props: any): void {
    const Component = props.component;
    this.root = ReactDOM.createRoot(element);
    this.root.render(React.createElement(Component, props));
  }

  unmount(element: HTMLElement): void {
    if (this.root) {
      this.root.unmount();
      this.root = null;
    }
  }

  update(element: HTMLElement, props: any): void {
    if (this.root) {
      const Component = props.component;
      this.root.render(React.createElement(Component, props));
    }
  }
}

// octo-core/src/adapters/vue.ts
import { createApp, App } from 'vue';
import { FrameworkAdapter } from './base';

export class VueAdapter implements FrameworkAdapter {
  private app: App | null = null;

  mount(element: HTMLElement, props: any): void {
    const Component = props.component;
    this.app = createApp(Component, props);
    this.app.mount(element);
  }

  unmount(element: HTMLElement): void {
    if (this.app) {
      this.app.unmount();
      this.app = null;
    }
  }

  update(element: HTMLElement, props: any): void {
    this.unmount(element);
    this.mount(element, props);
  }
}

