import express from 'express';
import handlebars from 'handlebars';
import { renderToString } from './renderers';

const app = express();

app.get('/components/:name', async (req, res) => {
  const { name } = req.params;
  const props = req.query;

  try {
    const component = await import(`./components/${name}`);
    const html = await renderToString(component.default, props);

    const template = handlebars.compile(`
      <!DOCTYPE html>
      <html>
        <head>
          <title>{{title}}</title>
          <link rel="stylesheet" href="/styles/{{name}}.css">
        </head>
        <body>
          <div id="app">{{{html}}}</div>
          <script>
            window.__INITIAL_PROPS__ = {{{props}}};
          </script>
          <script src="/bundles/{{name}}.js"></script>
        </body>
      </html>
    `);

    res.send(template({
      title: component.default.title || name,
      name,
      html,
      props: JSON.stringify(props)
    }));
  } catch (error) {
    res.status(500).send('Component not found');
  }
});

app.listen(3000, () => {
  console.log('Octo SSR server running on port 3000');
});

// octo-core/src/registry.ts
import { FrameworkAdapter } from './adapters/base';
import { ReactAdapter } from './adapters/react';
import { VueAdapter } from './adapters/vue';
import { SvelteAdapter } from './adapters/svelte';

interface ComponentDefinition {
  name: string;
  framework: 'react' | 'vue' | 'svelte' | 'preact';
  component: any;
  styles?: string;
}

class ComponentRegistry {
  private components = new Map<string, ComponentDefinition>();
  private adapters = new Map<string, FrameworkAdapter>();
  private mountedComponents = new Map<HTMLElement, { adapter: FrameworkAdapter; name: string }>();

  constructor() {
    this.adapters.set('react', new ReactAdapter());
    this.adapters.set('vue', new VueAdapter());
    this.adapters.set('svelte', new SvelteAdapter());
    this.adapters.set('preact', new ReactAdapter());
  }

  register(definition: ComponentDefinition): void {
    this.components.set(definition.name, definition);
    if (definition.styles) {
      this.injectStyles(definition.name, definition.styles);
    }
  }

  async mount(element: HTMLElement, name: string, props: any = {}): Promise<void> {
    const definition = this.components.get(name);
    if (!definition) {
      throw new Error(`Component ${name} not found`);
    }

    const adapter = this.adapters.get(definition.framework);
    if (!adapter) {
      throw new Error(`Adapter for ${definition.framework} not found`);
    }

    adapter.mount(element, { component: definition.component, ...props });
    this.mountedComponents.set(element, { adapter, name });
  }

  unmount(element: HTMLElement): void {
    const mounted = this.mountedComponents.get(element);
    if (mounted) {
      mounted.adapter.unmount(element);
      this.mountedComponents.delete(element);
    }
  }

  private injectStyles(name: string, styles: string): void {
    const styleId = `octo-styles-${name}`;
    if (!document.getElementById(styleId)) {
      const styleElement = document.createElement('style');
      styleElement.id = styleId;
      styleElement.textContent = styles;
      document.head.appendChild(styleElement);
    }
  }
}

export const registry = new ComponentRegistry();
export default registry;

