// octo-core/src/web-components.ts
import { registry } from './registry';

class OctoComponent extends HTMLElement {
  private mounted = false;

  static get observedAttributes() {
    return ['name', 'props'];
  }

  connectedCallback() {
    this.mount();
  }

  disconnectedCallback() {
    this.unmount();
  }

  attributeChangedCallback(name: string, oldValue: string, newValue: string) {
    if (this.mounted && oldValue !== newValue) {
      this.update();
    }
  }

  private async mount() {
    const componentName = this.getAttribute('name');
    if (!componentName) return;

    const propsAttr = this.getAttribute('props');
    const props = propsAttr ? JSON.parse(propsAttr) : {};

    await registry.mount(this, componentName, props);
    this.mounted = true;
  }

  private unmount() {
    registry.unmount(this);
    this.mounted = false;
  }

  private update() {
    this.unmount();
    this.mount();
  }
}

customElements.define('octo-component', OctoComponent);

// octo-core/src/loader.ts
export class ModuleLoader {
  private cache = new Map<string, any>();

  async load(url: string): Promise<any> {
    if (this.cache.has(url)) {
      return this.cache.get(url);
    }

    try {
      const module = await import(/* @vite-ignore */ url);
      this.cache.set(url, module);
      return module;
    } catch (error) {
      console.error(`Failed to load module from ${url}:`, error);
      throw error;
    }
  }

  async loadComponent(name: string, baseUrl: string = '/components'): Promise<any> {
    const url = `${baseUrl}/${name}/index.js`;
    return this.load(url);
  }

  clearCache(url?: string): void {
    if (url) {
      this.cache.delete(url);
    } else {
      this.cache.clear();
    }
  }
}

export const loader = new ModuleLoader();

