// octo-cli/src/webpack/config.ts
import { Configuration } from 'webpack';
import HtmlWebpackPlugin from 'html-webpack-plugin';
import MiniCssExtractPlugin from 'mini-css-extract-plugin';

interface OctoWebpackOptions {
  framework: 'react' | 'vue' | 'svelte';
  ssr: boolean;
  typescript: boolean;
}

export function generateWebpackConfig(options: OctoWebpackOptions): Configuration {
  const { framework, ssr, typescript } = options;

  return {
    mode: 'development',
    entry: './src/index.tsx',
    output: {
      filename: '[name].[contenthash].js',
      path: '/dist',
      clean: true,
    },
    module: {
      rules: [
        typescript && {
          test: /\.tsx?$/,
          use: 'ts-loader',
          exclude: /node_modules/,
        },
        {
          test: /\.jsx?$/,
          use: 'babel-loader',
          exclude: /node_modules/,
        },
        {
          test: /\.s?css$/,
          use: [
            ssr ? MiniCssExtractPlugin.loader : 'style-loader',
            'css-loader',
            'sass-loader',
          ],
        },
      ].filter(Boolean),
    },
    resolve: {
      extensions: ['.tsx', '.ts', '.jsx', '.js'],
    },
    plugins: [
      new HtmlWebpackPlugin({
        template: './public/index.html',
      }),
      ssr && new MiniCssExtractPlugin({
        filename: '[name].[contenthash].css',
      }),
    ].filter(Boolean),
    devServer: {
      port: 3000,
      hot: true,
    },
  };
}

// octo-vite-plugin/src/index.ts
import { Plugin } from 'vite';
import { transform } from './transformer';

interface OctoPluginOptions {
  framework?: 'react' | 'vue' | 'svelte';
  ssr?: boolean;
}

export function octoPlugin(options: OctoPluginOptions = {}): Plugin {
  return {
    name: 'vite-plugin-octo',

    config(config, { command }) {
      return {
        build: {
          lib: {
            entry: 'src/index.ts',
            formats: ['es', 'umd'],
            name: 'OctoComponent',
          },
        },
      };
    },

    transform(code, id) {
      if (id.endsWith('.octo')) {
        return transform(code, options);
      }
    },

    handleHotUpdate({ file, server }) {
      if (file.endsWith('.octo')) {
        server.ws.send({
          type: 'custom',
          event: 'octo-update',
          data: { file },
        });
      }
    },
  };
}

